package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import androidx.core.content.FileProvider;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

@androidx.media3.common.util.UnstableApi
public class ShareMediaTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private final List<File> files=new ArrayList<>();private final Set<String> before=new HashSet<>();private Activity activity;
 @Before public void before(){File[] dirs=new File(c.getCacheDir(),"shares").listFiles();if(dirs!=null)for(File f:dirs)before.add(f.getName());}
 private void remove(File f){if(f.isDirectory()){File[] all=f.listFiles();if(all!=null)for(File child:all)remove(child);}f.delete();}
 @After public void after(){if(activity!=null){ins.runOnMainSync(activity::finish);ins.waitForIdleSync();}for(File f:files)f.delete();File[] dirs=new File(c.getCacheDir(),"shares").listFiles();if(dirs!=null)for(File f:dirs)if(!before.contains(f.getName()))remove(f);}
 private File fixture(String asset,String suffix,boolean inside)throws Exception{File parent=inside?new File(c.getCacheDir(),"shares/test-"+UUID.randomUUID()):c.getCacheDir();if(!parent.isDirectory())assertTrue(parent.mkdirs());File f=File.createTempFile("onda-share-",suffix,parent);files.add(f);try(InputStream in=ins.getContext().getAssets().open(asset);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 private Uri stream(Intent send){return (Uri)send.getParcelableExtra(Intent.EXTRA_STREAM);}
 private byte[] bytes(Uri uri)throws Exception{try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){assertNotNull(in);byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 private void grant(Intent send,Uri expected,String type){assertEquals(Intent.ACTION_SEND,send.getAction());assertEquals(type,send.getType());assertEquals(expected,stream(send));assertEquals(expected,send.getClipData().getItemAt(0).getUri());assertTrue((send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,send.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);assertNull(send.getPackage());assertNull(send.getComponent());}
 @Test public void audioAndVideoContentUrisKeepOriginalFilesAndReadOnlyGrants()throws Exception{for(String[] source:new String[][]{{"audio-lossy.mp3",".mp3","audio/mpeg"},{"combined.mp4",".mp4","video/mp4"}}){File file=fixture(source[0],source[1],true);Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",file);Intent send=ShareMedia.prepare(c,uri,source[2],"Onda share",()->{});grant(send,uri,source[2]);assertArrayEquals(java.nio.file.Files.readAllBytes(file.toPath()),bytes(stream(send)));assertTrue(file.exists());}}
 @Test public void fileUrisUseOnlySelectedCopiesInTheNarrowProviderRoot()throws Exception{File file=fixture("combined.mp4",".mp4",false);try{FileProvider.getUriForFile(c,c.getPackageName()+".share",file);fail("Provider exposes cache outside shares");}catch(IllegalArgumentException expected){}Intent send=ShareMedia.prepare(c,Uri.fromFile(file),"video/mp4","Onda local video",()->{});Uri uri=stream(send);assertEquals("content",uri.getScheme());assertEquals(c.getPackageName()+".share",uri.getAuthority());grant(send,uri,"video/mp4");assertArrayEquals(java.nio.file.Files.readAllBytes(file.toPath()),bytes(uri));assertTrue(file.exists());try{ShareMedia.prepare(c,Uri.fromFile(file),"video/mp4","Cancelled",()->{throw new InterruptedIOException("cancelled");});fail();}catch(InterruptedIOException expected){}Intent link=ShareMedia.prepare(c,Uri.parse("https://example.org/video.mp4"),"video/mp4","Online",()->{});assertEquals("text/plain",link.getType());assertEquals("https://example.org/video.mp4",link.getStringExtra(Intent.EXTRA_TEXT));assertNull(stream(link));}
 @Test public void opensAndroidChooserWithoutChoosingARecipientOrSending()throws Exception{File file=fixture("audio-lossy.mp3",".mp3",true);Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",file);activity=ins.startActivitySync(new Intent(c,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));AtomicReference<Intent> selected=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_CHOOSER.equals(intent.getAction())){selected.set(intent);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(monitor);try{ins.runOnMainSync(()->ShareMedia.share(activity,uri,"audio/mpeg","Share native"));long until=android.os.SystemClock.elapsedRealtime()+15000;while(selected.get()==null&&android.os.SystemClock.elapsedRealtime()<until)Thread.sleep(50);assertNotNull("Android chooser was not opened",selected.get());Intent send=(Intent)selected.get().getParcelableExtra(Intent.EXTRA_INTENT);assertNotNull(send);grant(send,uri,"audio/mpeg");assertEquals(uri,selected.get().getClipData().getItemAt(0).getUri());assertNull(send.getStringArrayExtra(Intent.EXTRA_EMAIL));assertTrue(file.exists());}finally{ins.removeMonitor(monitor);}}
}
